export default async function(api) {
  const header=document.createElement('h3');
  header.textContent='Signed external plugin demo';
  const response=document.createElement('pre');
  response.textContent='Verifying publisher and requesting host:info...';
  api.root.append(header,response);
  try {
    const info=await api.hostInfo();
    response.textContent=info.appName+' / '+info.apiVersion+'\nSigned publisher: '+info.publisherId;
    api.log('host:info succeeded');
  } catch (error) {
    response.textContent='Host API refused: '+String(error);
    api.log('host:info denied');
  }
}
